function flatten(payload, prefix = "") {
  let out = [];
  for (const [key, val] of Object.entries(payload)) {
    if (val && typeof val === "object" && !Array.isArray(val)) out.push(...flatten(val, prefix + key + "."));
    else out.push([prefix + key, val]);
  }
  return out;
}
